def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    dangerous_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    expected_winners = supply / float(WATER_REQ)
    tight_supply = expected_winners < 2.0
    medium_supply = expected_winners < 3.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_prev = max(dangerous_bids) if dangerous_bids else highest_prev

    if hp <= 2 or no_water >= 2:
        bid = max(110.0, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        if tight_supply:
            bid = max(108.0, highest_prev + 1.5)
        else:
            bid = max(92.0, urgent_prev + 1.0)
    else:
        if tight_supply:
            bid = max(100.0, highest_prev + 1.0)
        elif medium_supply:
            bid = 72.0 if highest_prev > 105.0 else max(66.0, highest_prev * 0.72)
        else:
            bid = 38.0 if highest_prev > 100.0 else 52.0

    if day >= 8 and hp >= 7 and no_water == 0:
        bid *= 0.9

    reserve_floor = 0.0
    if hp > 4:
        reserve_floor = DAILY_SALARY * max(0, 10 - day) * 0.18
    spendable = max(0.0, budget - reserve_floor)
    if spendable <= 0:
        spendable = min(budget, DAILY_SALARY * 0.75)

    final_bid = min(float(budget), float(spendable), float(bid))
    if final_bid < 0:
        final_bid = 0.0
    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents only
    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    # If no opponents, secure enough water cheaply
    if not alive_opponents:
        target = 1.0 * DAILY_SALARY * 0.4
        if my_status['budget'] is None:
            return 0
        return min(float(my_status['budget']), target)

    # Inspect yesterday bids for immediate pressure signal
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are feasible; map supply to a pressure level.
    # Use int() to avoid float index issues.
    # For our requirement 9, supply 15-25 implies 1 unit always, sometimes 2 units depending on exact rules.
    # We still bid to win at least one unit.
    units_possible = int(supply / float(WATER_REQ))
    if units_possible < 1:
        units_possible = 1

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Strategy:
    # - If we're in danger (low hp or accumulating no-water days), bid aggressively.
    # - If yesterday had very high bids (Cindy/Eric ~100+), don't fully match; bid moderately above the level needed.
    # - Otherwise, bid around a mid level to secure water.
    danger = (hp <= 2.0) or (no_water_days >= 2)

    if max_prev_bid >= 105.0:
        # High competition; scale down vs max to avoid overpaying
        if danger:
            bid = DAILY_SALARY * 0.85
        else:
            bid = max(DAILY_SALARY * 0.55, max_prev_bid * 0.35)
    elif max_prev_bid >= 70.0:
        if danger:
            bid = DAILY_SALARY * 0.75
        else:
            bid = max(DAILY_SALARY * 0.48, max_prev_bid * 0.25)
    else:
        if danger:
            bid = DAILY_SALARY * 0.65
        else:
            bid = DAILY_SALARY * 0.42

    # Adjust slightly by supply: higher supply reduces need to overbid
    # supply in [15,25] => factor in [1.05..0.95]
    if supply >= float(MAX_SUPPLY):
        bid *= 0.95
    elif supply <= float(MIN_SUPPLY):
        bid *= 1.05

    # Final clamp to budget and non-negative
    if budget <= 0:
        return 0.0
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    # Keep bids from going beyond what we'd reasonably pay for one unit
    # (acts as a soft cap)
    soft_cap = max(DAILY_SALARY * 0.95, max_prev_bid * 0.6)
    if bid > soft_cap:
        bid = soft_cap

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], 95.0)

    if supply < 18:
        return min(my_status['budget'], max(75.0, avg_prev_bid + 5.0))

    return min(my_status['budget'], max(45.0, avg_prev_bid * 0.9))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, SALARY * 0.4)

    # Check yesterday's trace for Cindy (or highest bidder)
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    max_prev = max(prev_bids) if prev_bids else 0

    # Emergency if no water for 2+ days or hp critical
    if no_water_days >= 2 or hp <= 2:
        return min(budget, SALARY * 0.95)

    # If supply low and we have many days left, be aggressive
    days_left = 10 - day
    supply_per_capita = supply / (len(alive_opponents) + 1)
    if supply_per_capita < WATER_REQ:
        # scarcity: need to bid high
        target = max(SALARY * 0.85, max_prev + 2)
        return min(budget, target)

    # Normal: try to outbid previous max slightly if we can afford, else conservative
    if budget > max_prev + 5:
        return min(budget, max_prev + 3)
    else:
        return min(budget, SALARY * 0.6)
